{
  "title": "Cusco Close to Home",
  "summary": "A relaxed Sunday around the city centre, with market life, the grand plaza and a proper sit-down meal, all within a short stroll.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "We start here for the morning bustle and cheap local bites, and because it sits right beside everything else today.",
      "note": "We start here for the morning bustle and cheap local bites, and because it sits right beside everything else today."
    },
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short wander from the market, this is the postcard heart of Cusco and costs nothing but a little awe.",
      "note": "A short wander from the market, this is the postcard heart of Cusco and costs nothing but a little awe."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch is right by the plaza, so nobody has to chase a long ride on a full stomach.",
      "note": "Lunch is right by the plaza, so nobody has to chase a long ride on a full stomach."
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "After lunch we slip into the cathedral for a little shade and a lot of history, still in the same few blocks.",
      "note": "After lunch we slip into the cathedral for a little shade and a lot of history, still in the same few blocks."
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner is the easy-going, budget-friendly pick, and it keeps our evening close to the centre.",
      "note": "Dinner is the easy-going, budget-friendly pick, and it keeps our evening close to the centre."
    }
  ]
}
